<template>
  <ConfirmationDialog2
    title="Account Deletion"
    :description="`Are you sure you want to delete ${userName ? userName : 'your'}'s account? This action cannot be undone.`"
    confirm-btn-text="Confirm Delete"
    confirm-btn-variant="destructive"
    :is-confirm-loading="isDeletingUser"
    :is-awaited-close="true"
    :confirm="
      async () => {
        if (userId) await deleteUser(userId);
      }
    "
    ><Button variant="destructive" class="w-fit" :disabled="isDeletingUser">Delete Account</Button></ConfirmationDialog2
  >
</template>

<script setup lang="ts">
import { useDeleteUser } from '~/mutations/users/deleteUser';

interface Props {
  userId: string | undefined;
  userName?: string;
}

defineProps<Props>();

const { deleteUser, isDeletingUser } = useDeleteUser();
</script>
