import { deleteAccount, logout } from '~/client';
import type { DeleteAccountResponse, UserDetailsResponse, UserStatus } from '~/client';

export const useDeleteUser = defineMutation(() => {
  const queryCache = useQueryCache();
  const route = useRoute();

  const { mutateAsync: deleteUser, asyncStatus } = useMutation({
    mutation: (userId: string): Promise<DeleteAccountResponse> =>
      deleteAccount({ composable: '$fetch', path: { user_id: userId } }),
    onSuccess: async (_, userId) => {
      if (route.name === 'users-id') {
        const { userId: currentUserId } = useUserRole();
        if (userId === currentUserId.value) {
          await onDeleteCurrentUser();
        } else {
          queryCache.setQueryData(['user', userId], (oldData?: UserDetailsResponse) => {
            return {
              ...oldData!,
              status: 'deleted' as UserStatus,
            };
          });
        }
      } else if (route.name === 'account') {
        await onDeleteCurrentUser();
      }
      showToastSuccess('User account deleted successfully.');
    },
    onError: (err) => {
      showToastError(err);
    },
  });

  return {
    deleteUser,
    isDeletingUser: computed(() => asyncStatus.value === 'loading'),
  };
});

const onDeleteCurrentUser = async () => {
  const { signOut } = useAuth();
  await signOut();
};
