<template>
  <LabeledValueIcon
    :to="isAdmin ? { name: 'subcontractor-companies-id', params: { id: subcontractorCompanyId } } : undefined"
    :label="label || 'Subcontractor Company'"
    :value="companyName"
    :icon="Building2"
    :loading="isLoading"
    :error="error ? 'Failed to load subcontractor company' : undefined"
  />
</template>
<script setup lang="ts">
import { Building2 } from 'lucide-vue-next';
import LabeledValueIcon from '~/components/common/LabeledValueIcon.vue';
import { getSubcontractorCompanyShortInfo } from '~/client';

const props = defineProps<{
  label?: string;
  subcontractorCompanyId: string;
}>();

const { data, isLoading, error } = useQuery({
  key: () => ['subcontractor-company.short-info', props.subcontractorCompanyId],
  query: () =>
    getSubcontractorCompanyShortInfo({
      composable: '$fetch',
      path: { subcontractor_company_id: props.subcontractorCompanyId },
    }),
  enabled: () => !!props.subcontractorCompanyId,
});

const companyName = computed(() => data.value?.name);

const { isAdmin } = useUserRole();
</script>
